# ========================
# Avro reader
# ========================

def avro_read_long(data, pos):
    """Read Avro zigzag-encoded long."""
    n, pos = protobuf_read_varint(data, pos)
    return (n >> 1) ^ -(n & 1), pos

def avro_read_string(data, pos):
    length, pos = avro_read_long(data, pos)
    s = data[pos:pos+length].decode('utf-8', errors='replace')
    return s, pos + length

def avro_read_bytes(data, pos):
    length, pos = avro_read_long(data, pos)
    return data[pos:pos+length], pos + length

def avro_decode_datum(data, pos, schema):
    """Decode a single Avro datum based on schema."""
    schema_type = schema.get('type') if isinstance(schema, dict) else schema

    if isinstance(schema_type, list):
        # Union type
        # Read index (long) to determine which type
        idx, pos = avro_read_long(data, pos)
        chosen = schema_type[idx]
        if chosen == 'null':
            return None, pos
        return avro_decode_datum(data, pos, chosen)

    if schema_type == 'null':
        return None, pos
    elif schema_type == 'boolean':
        val = data[pos] != 0
        pos += 1
        return val, pos
    elif schema_type == 'int':
        n, pos = avro_read_long(data, pos)
        return n, pos
    elif schema_type == 'long':
        n, pos = avro_read_long(data, pos)
        return n, pos
    elif schema_type == 'float':
        val = struct.unpack_from('<f', data, pos)[0]
        return val, pos + 4
    elif schema_type == 'double':
        val = struct.unpack_from('<d', data, pos)[0]
        return val, pos + 8
    elif schema_type == 'string':
        return avro_read_string(data, pos)
    elif schema_type == 'bytes':
        b, pos = avro_read_bytes(data, pos)
        return b, pos
    elif schema_type == 'record':
        fields = schema.get('fields', [])
        result = {}
        for field in fields:
            field_name = field.get('name', '')
            field_schema = field.get('type')
            val, pos = avro_decode_datum(data, pos, field_schema)
            result[field_name] = val
        return result, pos
    elif schema_type == 'array':
        items_schema = schema.get('items')
        result = []
        while True:
            count, pos = avro_read_long(data, pos)
            if count == 0:
                break
            if count < 0:
                # Negative means size in bytes follows, then |count| items
                _, pos = avro_read_long(data, pos)
                count = -count
            for _ in range(count):
                item, pos = avro_decode_datum(data, pos, items_schema)
                result.append(item)
        return result, pos
    elif schema_type == 'map':
        values_schema = schema.get('values')
        result = {}
        while True:
            count, pos = avro_read_long(data, pos)
            if count == 0:
                break
            if count < 0:
                _, pos = avro_read_long(data, pos)
                count = -count
            for _ in range(count):
                key, pos = avro_read_string(data, pos)
                val, pos = avro_decode_datum(data, pos, values_schema)
                result[key] = val
        return result, pos
    elif schema_type == 'enum':
        idx, pos = avro_read_long(data, pos)
        symbols = schema.get('symbols', [])
        val = symbols[idx] if idx < len(symbols) else str(idx)
        return val, pos
    elif schema_type == 'fixed':
        size = schema.get('size', 0)
        val = data[pos:pos+size]
        return val, pos + size
    elif isinstance(schema_type, dict):
        return avro_decode_datum(data, pos, schema_type)
    else:
        return None, pos

def read_avro(filepath):
    """Read an Avro file and return list of row dicts."""
    with open(filepath, 'rb') as f:
        data = f.read()

    if data[:4] != b'Obj\x01':
        raise ValueError("Not a valid Avro file")

    pos = 4

    # Read header metadata
    avro_schema = None
    avro_codec = 'null'

    while True:
        count, pos = avro_read_long(data, pos)
        if count == 0:
            break
        abs_count = abs(count)
        if count < 0:
            _, pos = avro_read_long(data, pos)  # block size
        for _ in range(abs_count):
            key, pos = avro_read_string(data, pos)
            val, pos = avro_read_bytes(data, pos)
            if key == 'avro.schema':
                avro_schema = json.loads(val.decode('utf-8'))
            elif key == 'avro.codec':
                avro_codec = val.decode('utf-8')

    # Read sync marker (16 bytes)
    sync_marker = data[pos:pos+16]
    pos += 16

    if avro_schema is None:
        return []

    # Read data blocks
    rows = []

    while pos < len(data) - 16:
        # Read object count
        obj_count, pos = avro_read_long(data, pos)
        if obj_count == 0:
            break

        # Read block byte count
        block_size, pos = avro_read_long(data, pos)

        # Read block data
        block_data = data[pos:pos+block_size]
        pos += block_size

        # Check sync marker
        if data[pos:pos+16] == sync_marker:
            pos += 16

        # Decompress block
        if avro_codec == 'snappy':
            # Snappy: compressed data + 4-byte CRC32
            compressed = block_data[:-4]
            block_data = decompress_snappy(compressed)
        elif avro_codec == 'deflate':
            block_data = zlib.decompress(block_data, -15)
        elif avro_codec == 'null':
            pass

        # Decode records
        block_pos = 0
        for _ in range(abs(obj_count)):
            try:
                record, block_pos = avro_decode_datum(block_data, block_pos, avro_schema)
                if isinstance(record, dict):
                    rows.append(record)
            except Exception:
                break

    return rows

