# ========================
# Excel (xlsx) reader
# ========================

def read_xlsx(filepath):
    """Read an Excel xlsx file and return list of row dicts (or dict of sheets for multi-sheet)."""
    try:
        with zipfile.ZipFile(filepath, 'r') as z:
            # Read workbook to get sheet names
            wb_xml = z.read('xl/workbook.xml')
            wb_tree = ET.fromstring(wb_xml)

            # Namespace handling
            ns = {'main': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
                  'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'}

            # Get sheet info
            sheets = []
            for sheet in wb_tree.findall('.//{http://schemas.openxmlformats.org/spreadsheetml/2006/main}sheet'):
                name = sheet.get('name', '')
                rid = sheet.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id', '')
                sheets.append({'name': name, 'rid': rid})

            # Read relationships
