def read_logfmt(filepath):
    """Read a logfmt file and return list of row dicts."""
    rows = []
    with open(filepath, 'r', encoding='utf-8', errors='replace') as f:
        for line in f:
            line = line.rstrip('\n\r')
            if not line:
                continue
            row = parse_logfmt_line(line)
            rows.append(row)
    return rows

def parse_logfmt_line(line):
    """Parse a single logfmt line into a dict."""
    result = {}
    pos = 0
    n = len(line)

    while pos < n:
        # Skip whitespace
        while pos < n and line[pos] == ' ':
            pos += 1
        if pos >= n:
            break

        # Read key
        key_start = pos
        while pos < n and line[pos] != '=' and line[pos] != ' ':
            pos += 1
        key = line[key_start:pos]

        if not key:
            pos += 1
            continue

        if pos >= n or line[pos] != '=':
            # Key without value
            result[key] = ''
            continue

        pos += 1  # skip '='

        if pos >= n:
            result[key] = ''
            continue

        # Read value
        if line[pos] == '"':
            # Quoted value
            pos += 1
            val_parts = []
            while pos < n:
                if line[pos] == '"':
                    pos += 1
                    break
                elif line[pos] == '\\' and pos + 1 < n:
                    pos += 1
                    c = line[pos]
                    if c == 'n':
                        val_parts.append('\n')
                    elif c == 't':
                        val_parts.append('\t')
                    elif c == '"':
                        val_parts.append('"')
                    elif c == '\\':
                        val_parts.append('\\')
                    else:
                        val_parts.append(c)
                    pos += 1
                else:
                    val_parts.append(line[pos])
                    pos += 1
            result[key] = ''.join(val_parts)
        else:
            # Unquoted value
            val_start = pos
            while pos < n and line[pos] != ' ':
                pos += 1
            result[key] = line[val_start:pos]

    return result

def read_logfmt_stdin(data):
    """Parse logfmt from bytes/string."""
    if isinstance(data, bytes):
        data = data.decode('utf-8', errors='replace')
    rows = []
    for line in data.split('\n'):
        line = line.rstrip('\r')
        if not line:
            continue
        rows.append(parse_logfmt_line(line))
    return rows

