# ========================
# Schema inference
# ========================

def infer_schema(data):
    """Infer schema from data (list or dict)."""
    if isinstance(data, list):
        if len(data) == 0:
            return {"kind": "array", "array": {"kind": "unknown"}}
        # Infer item schema from all items
        if all(isinstance(item, dict) for item in data):
            # Merge all object schemas
            all_keys = {}
            for item in data:
                for k, v in item.items():
                    val_schema = infer_value_schema(v)
                    if k not in all_keys:
                        all_keys[k] = val_schema
                    else:
                        all_keys[k] = merge_schemas(all_keys[k], val_schema)
            return {"kind": "array", "array": {"kind": "object", "object": all_keys}}
        else:
            item_schema = {"kind": "unknown"}
            for item in data:
                s = infer_value_schema(item)
                item_schema = merge_schemas(item_schema, s)
            return {"kind": "array", "array": item_schema}
    elif isinstance(data, dict):
        obj = {}
        for k, v in data.items():
            obj[k] = infer_value_schema(v)
        return {"kind": "object", "object": obj}
    else:
        return infer_value_schema(data)

def infer_value_schema(v):
    """Infer schema for a single value."""
    if v is None:
