# ========================

def infer_schema(data):
    """Infer schema from data (list or dict)."""
    if isinstance(data, list):
        if len(data) == 0:
            return {"kind": "array", "array": {"kind": "unknown"}}
        # Infer item schema from all items
        if all(isinstance(item, dict) for item in data):
            # Merge all object schemas
            all_keys = {}
            for item in data:
                for k, v in item.items():
                    val_schema = infer_value_schema(v)
                    if k not in all_keys:
                        all_keys[k] = val_schema
                    else:
                        all_keys[k] = merge_schemas(all_keys[k], val_schema)
            return {"kind": "array", "array": {"kind": "object", "object": all_keys}}
        else:
            item_schema = {"kind": "unknown"}
            for item in data:
                s = infer_value_schema(item)
                item_schema = merge_schemas(item_schema, s)
            return {"kind": "array", "array": item_schema}
    elif isinstance(data, dict):
        obj = {}
        for k, v in data.items():
            obj[k] = infer_value_schema(v)
        return {"kind": "object", "object": obj}
    else:
        return infer_value_schema(data)

def infer_value_schema(v):
    """Infer schema for a single value."""
    if v is None:
        return {"kind": "unknown"}
    elif isinstance(v, bool):
        return {"kind": "scalar", "scalar": "boolean"}
    elif isinstance(v, (int, float)):
        return {"kind": "scalar", "scalar": "number"}
    elif isinstance(v, str):
        return {"kind": "scalar", "scalar": "string"}
    elif isinstance(v, list):
        if len(v) == 0:
            return {"kind": "array", "array": {"kind": "unknown"}}
        item_schema = {"kind": "unknown"}
        for item in v:
            s = infer_value_schema(item)
            item_schema = merge_schemas(item_schema, s)
        return {"kind": "array", "array": item_schema}
    elif isinstance(v, dict):
        obj = {}
        for k, val in v.items():
            obj[k] = infer_value_schema(val)
        return {"kind": "object", "object": obj}
    else:
        return {"kind": "scalar", "scalar": "string"}

def merge_schemas(s1, s2):
    """Merge two schemas into a combined schema."""
    if s1 == s2:
        return s1

    k1 = s1.get('kind')
    k2 = s2.get('kind')

    if k1 == 'unknown':
        return s2
    if k2 == 'unknown':
        return s1

    if k1 == k2:
        if k1 == 'scalar':
            if s1.get('scalar') == s2.get('scalar'):
                return s1
            return {"kind": "varied", "varied": [s1, s2]}
        elif k1 == 'array':
            merged = merge_schemas(s1.get('array', {}), s2.get('array', {}))
            return {"kind": "array", "array": merged}
        elif k1 == 'object':
            obj1 = s1.get('object', {})
            obj2 = s2.get('object', {})
            merged = {}
            all_keys = set(list(obj1.keys()) + list(obj2.keys()))
            for k in all_keys:
                if k in obj1 and k in obj2:
                    merged[k] = merge_schemas(obj1[k], obj2[k])
                elif k in obj1:
                    merged[k] = merge_schemas(obj1[k], {"kind": "unknown"})
                else:
                    merged[k] = merge_schemas({"kind": "unknown"}, obj2[k])
            return {"kind": "object", "object": merged}
        elif k1 == 'varied':
            # Add to varied list
            varied1 = s1.get('varied', [])
            return {"kind": "varied", "varied": varied1 + [s2]}

    # Different kinds
    if k1 == 'varied':
        varied1 = s1.get('varied', [])
        return {"kind": "varied", "varied": varied1 + [s2]}
    if k2 == 'varied':
        varied2 = s2.get('varied', [])
        return {"kind": "varied", "varied": [s1] + varied2}

    return {"kind": "varied", "varied": [s1, s2]}

# ========================
# SQLite loading
# ========================

def flatten_dict(d, prefix=''):
    """Flatten a nested dict with dot notation."""
    result = {}
    for k, v in d.items():
        new_key = f"{prefix}.{k}" if prefix else k
        if isinstance(v, dict):
            result.update(flatten_dict(v, new_key))
        elif isinstance(v, list):
            result[new_key] = json.dumps(v, separators=(',', ':'))
        else:
            result[new_key] = v
    return result

def infer_column_types(rows):
    """Determine SQLite column types for each column based on data."""
    if not rows:
        return {}

    col_types = {}
    col_values = {}  # col -> list of non-null values

    for row in rows:
        for k, v in row.items():
            if k not in col_values:
                col_values[k] = []
            if v is not None:
                col_values[k].append(v)

    for col, values in col_values.items():
        if not values:
            col_types[col] = 'TEXT'
            continue

        all_bool = all(isinstance(v, bool) for v in values)
        all_int = all(isinstance(v, (int, bool)) and not isinstance(v, float) for v in values) and not all_bool
        all_number = all(isinstance(v, (int, float, bool)) for v in values)
        all_str = all(isinstance(v, str) for v in values)

        has_null = any(row.get(col) is None for row in rows)

        if all_bool:
            if has_null:
                col_types[col] = 'TEXT'
            else:
                col_types[col] = 'INTEGER'
        elif all_number:
            if has_null:
                col_types[col] = 'TEXT'
            else:
                col_types[col] = 'NUMERIC'
        elif all_str:
            col_types[col] = 'TEXT'
        else:
            col_types[col] = 'TEXT'

    return col_types

def load_rows_into_sqlite(conn, table_name, rows):
    """Load rows into an SQLite table."""
    if not rows:
        # Create empty table with no rows
        conn.execute(f'CREATE TABLE IF NOT EXISTS "{table_name}" (_dummy TEXT)')
        return

    # Flatten rows if nested
    flat_rows = []
    for row in rows:
        if isinstance(row, dict):
            flat = flatten_dict(row)
            flat_rows.append(flat)
        else:
            flat_rows.append({'value': row})

    if not flat_rows:
        conn.execute(f'CREATE TABLE IF NOT EXISTS "{table_name}" (_dummy TEXT)')
        return

    # Collect all columns
    all_cols = []
    seen_cols = set()
    for row in flat_rows:
        for k in row.keys():
            if k not in seen_cols:
                all_cols.append(k)
                seen_cols.add(k)

    # Determine column types
    col_types = infer_column_types(flat_rows)

    # Create table
    col_defs = []
    for col in all_cols:
        ct = col_types.get(col, 'TEXT')
        col_defs.append(f'"{col}" {ct}')

    create_sql = f'CREATE TABLE "{table_name}" ({", ".join(col_defs)})'
    conn.execute(create_sql)

    # Insert rows
    placeholders = ', '.join(['?' for _ in all_cols])
    insert_sql = f'INSERT INTO "{table_name}" ({", ".join(chr(34)+c+chr(34) for c in all_cols)}) VALUES ({placeholders})'

    for row in flat_rows:
        values = []
        for col in all_cols:
            v = row.get(col)
            ct = col_types.get(col, 'TEXT')

            if v is None:
                values.append(None)
            elif ct == 'INTEGER':
                if isinstance(v, bool):
                    values.append(1 if v else 0)
                else:
                    try:
                        values.append(int(v))
                    except (ValueError, TypeError):
                        values.append(str(v))
            elif ct == 'NUMERIC':
                if isinstance(v, bool):
                    values.append(1 if v else 0)
                elif isinstance(v, (int, float)):
                    values.append(v)
                else:
                    # Was "1.0" type - convert
                    try:
                        fv = float(str(v))
                        if fv == int(fv):
                            values.append(int(fv))
                        else:
                            values.append(fv)
                    except (ValueError, TypeError):
                        values.append(str(v))
            else:
                # TEXT
                if isinstance(v, bool):
                    values.append(str(int(v)))
                elif isinstance(v, (int, float)):
                    fv = float(v)
                    if fv == int(fv):
                        values.append(str(int(fv)))
                    else:
                        values.append(str(v))
                elif isinstance(v, bytes):
                    values.append(v.decode('utf-8', errors='replace'))
                else:
                    values.append(str(v) if v is not None else None)

        conn.execute(insert_sql, values)

    conn.commit()

