MIME_TYPES = {
    '.csv': 'csv',
    '.tsv': 'tsv',
    '.json': 'json',
    '.ndjson': 'ndjson',
    '.jsonl': 'ndjson',
    '.parquet': 'parquet',
    '.xlsx': 'xlsx',
    '.ods': 'ods',
    '.avro': 'avro',
    '.orc': 'orc',
    '.logfmt': 'logfmt',
}

def detect_format(filepath):
    """Detect file format from extension."""
    _, ext = os.path.splitext(filepath)
    ext = ext.lower()
    return MIME_TYPES.get(ext)

def load_file(filepath, fmt=None):
    """Load a file and return (rows_or_data, raw_content, is_dumpable)."""
    if fmt is None:
        fmt = detect_format(filepath)

    if fmt is None:
        raise ValueError(f"Unknown mimetype for file: {filepath}.")

    if fmt == 'csv':
        rows = read_csv(filepath, ',')
        return rows, None, False
    elif fmt == 'tsv':
        rows = read_csv(filepath, '\t')
        return rows, None, False
    elif fmt == 'json':
        data, raw_content = read_json(filepath)
        return data, raw_content, True  # dumpable (raw content)
    elif fmt == 'ndjson':
        rows = read_ndjson(filepath)
        return rows, None, False
    elif fmt == 'parquet':
        rows = read_parquet(filepath)
        return rows, None, False
    elif fmt == 'xlsx':
        data = read_xlsx(filepath)
        return data, None, False
    elif fmt == 'ods':
        rows = read_ods(filepath)
        return rows, None, False
    elif fmt == 'avro':
        rows = read_avro(filepath)
        return rows, None, False
    elif fmt == 'orc':
        rows = read_orc(filepath)
        return rows, None, False
    elif fmt == 'logfmt':
        rows = read_logfmt(filepath)
        return rows, None, False
    else:
        raise ValueError(f"Unknown mimetype for file: {filepath}.")

def load_stdin(fmt):
    """Load data from stdin."""
    raw = sys.stdin.buffer.read()

    if fmt == 'csv':
        rows = read_csv_from_data(raw, ',')
        return rows, None, False
    elif fmt == 'tsv':
        rows = read_csv_from_data(raw, '\t')
        return rows, None, False
    elif fmt == 'json':
        content = raw.decode('utf-8', errors='replace')
        try:
            data = json.loads(content)
            return data, content, True
        except json.JSONDecodeError as e:
            raise ValueError(f"invalid character looking for beginning of value")
    elif fmt == 'ndjson':
        content = raw.decode('utf-8', errors='replace')
        rows = []
        for line in content.split('\n'):
            line = line.strip()
            if not line:
                continue
            try:
                obj = json.loads(line)
                if isinstance(obj, dict):
                    rows.append(obj)
            except json.JSONDecodeError:
                continue
        return rows, None, False
    elif fmt == 'logfmt':
        rows = read_logfmt_stdin(raw)
        return rows, None, False
    else:
        raise ValueError(f"Unknown mimetype for format: {fmt}.")

