# ========================
# Pretty table printer
# ========================

def print_pretty_table(rows, columns):
    """Print a pretty table to stdout."""
    if not rows or not columns:
        return

    # Sort columns alphabetically
    sorted_cols = sorted(columns)

    # Calculate column widths
    widths = {}
    for col in sorted_cols:
        widths[col] = len(col)

    for row in rows:
        for col in sorted_cols:
            val = row.get(col)
            s = format_value_for_table(val)
            widths[col] = max(widths[col], len(s))

    # Print header
    separator = '+' + '+'.join('-' * (widths[c] + 2) for c in sorted_cols) + '+'
    header = '|' + '|'.join(f' {c.center(widths[c])} ' for c in sorted_cols) + '|'

    print(separator)
    print(header)
    print(separator)

    # Print rows
    for row in rows:
        cells = []
        for col in sorted_cols:
            val = row.get(col)
            s = format_value_for_table(val)
            w = widths[col]

            # Right-align numbers, left-align everything else
            if is_numeric_value(val):
                cells.append(f' {s.rjust(w)} ')
            else:
                cells.append(f' {s.ljust(w)} ')

        print('|' + '|'.join(cells) + '|')

    print(separator)

    n = len(rows)
    if n == 1:
        print(f'({n} row)')
    else:
        print(f'({n} rows)')

def format_value_for_table(val):
    """Format a value for display in a table."""
    if val is None:
        return 'null'
    elif isinstance(val, bool):
        return 'true' if val else 'false'
    elif isinstance(val, float):
        if val == int(val):
            return str(int(val))
        return str(val)
    elif isinstance(val, int):
        return str(val)
    else:
        return str(val)

def is_numeric_value(val):
    """Check if a value should be right-aligned."""
    if val is None:
        return False
    if isinstance(val, bool):
        return False
    if isinstance(val, (int, float)):
        return True
    if isinstance(val, str):
        try:
            float(val)
            return True
        except (ValueError, TypeError):
            return False
    return False

# ========================
# Output formatting
# ========================

def format_query_results(rows, columns):
    """Format query results as JSON array."""
    if not rows:
        sys.stdout.write('[]\n')
        return

    if len(rows) == 1:
        sys.stdout.write('[' + row_to_json_str(rows[0]) + ']\n')
        return

    parts = []
    for row in rows:
        parts.append(row_to_json_str(row))

    sys.stdout.write('[' + ',\n'.join(parts) + ']\n')

def row_from_sqlite(cursor_row, column_names):
    """Convert a sqlite3 cursor row to a dict."""
    result = {}
    for i, name in enumerate(column_names):
        val = cursor_row[i]
        # Convert TEXT "1.0" to proper number if it looks like a number
        if isinstance(val, str):
            # Keep as string
            pass
        elif isinstance(val, float):
            # Check if it's a whole number
            if val == int(val) and not (val != val):
                val = int(val)
        result[name] = val
    return result

