# Test the ThriftReader directly
class ThriftReader:
    def __init__(self, data, pos=0):
        self.data = data
        self.pos = pos

    def read_varint(self):
        result = 0
        shift = 0
        while self.pos < len(self.data):
            b = self.data[self.pos]
            self.pos += 1
            result |= (b & 0x7f) << shift
            if not (b & 0x80):
                break
            shift += 7
        return result

    def read_i32(self):
        n = self.read_varint()
        return (n >> 1) ^ -(n & 1)

    def read_i64(self):
        n = self.read_varint()
        return (n >> 1) ^ -(n & 1)

    def read_binary(self):
        length = self.read_varint()
        val = self.data[self.pos:self.pos+length]
        self.pos += length
        return val

    def read_string(self):
        return self.read_binary().decode('utf-8', errors='replace')

    def read_list_header(self):
        b = self.data[self.pos]
        self.pos += 1
        elem_type = b & 0x0f
        size = (b >> 4) & 0x0f
        if size == 0x0f:
            size = self.read_varint()
        return elem_type, size

    def read_field_header(self, last_field_id):
        if self.pos >= len(self.data):
            return 0, 0
        b = self.data[self.pos]
        self.pos += 1
        if b == 0:
            return 0, 0
        type_id = b & 0x0f
        delta = (b >> 4) & 0x0f
        if delta == 0:
            field_id_raw = self.read_varint()
            field_id = (field_id_raw >> 1) ^ -(field_id_raw & 1)
        else:
            field_id = last_field_id + delta
        return field_id, type_id

    def skip_field(self, type_id):
        if type_id in (1, 2):
            pass
        elif type_id == 3:
            self.pos += 1
        elif type_id in (4, 5, 6):
            self.read_varint()
        elif type_id == 7:
            self.pos += 8
        elif type_id == 8:
            length = self.read_varint()
            self.pos += length
        elif type_id in (9, 10):
            elem_type, size = self.read_list_header()
            for _ in range(size):
                self.skip_field(elem_type)
        elif type_id == 11:
            b = self.data[self.pos]; self.pos += 1
            size = self.read_varint()
            key_type = (b >> 4) & 0x0f
            val_type = b & 0x0f
            for _ in range(size):
                self.skip_field(key_type)
                self.skip_field(val_type)
        elif type_id == 12:
            last_id = 0
            while True:
                fid, ftype = self.read_field_header(last_id)
                if fid == 0:
                    break
                last_id = fid
                self.skip_field(ftype)

    def read_struct_fields(self):
        last_id = 0
        while True:
            fid, ftype = self.read_field_header(last_id)
            if fid == 0:
