old_arr_schema = '''        if all(isinstance(item, dict) for item in data):
            # Collect all keys across all rows
            all_key_set = set()
            for item in data:
                all_key_set.update(item.keys())

            # Merge schemas including presence/absence
            all_keys = {}
            for k in all_key_set:
                val_schema = {"kind": "unknown"}
                for item in data:
                    if k in item:
                        s = infer_value_schema(item[k])
                    else:
                        s = {"kind": "scalar", "scalar": "null"}  # absent key = null
                    val_schema = merge_schemas(val_schema, s)
                all_keys[k] = val_schema
            return {"kind": "array", "array": {"kind": "object", "object": all_keys}}'''

